def apply_allocation(model, allocation):
    """Apply per-head quantization allocation."""
    for key, (action, bits) in allocation.items():
        parts = key.split(",")
        layer_idx = int(parts[0])
        head_idx = int(parts[1])
        if action == "quant" and bits < 16:
            patch_attention_gemma2(model, layer_idx, head_idx, n_bits=bits)

