def build_uniform_allocation(n_layers, n_heads, bits=4):
    """Build allocation dict with all heads at the same bitwidth."""
    alloc = {}
    for l in range(n_layers):
        for h in range(n_heads):
            alloc[f"{l},{h}"] = ["quant", bits]
    return alloc
